    island_id = 2
    area_map = {}
    def dfs(r, c, i_id):
        if r < 0 or r >= n or c < 0 or c >= n or grid[r][c] != 1:
            return 0
        grid[r][c] = i_id
        return 1 + dfs(r + 1, c, i_id) + dfs(r - 1, c, i_id) + dfs(r, c + 1, i_id) + dfs(r, c - 1, i_id)
    max_area = 0
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                area_map[island_id] = dfs(r, c, island_id)
                max_area = max(max_area, area_map[island_id])
                island_id += 1
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                neighbors = set()
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] > 1:
                        neighbors.add(grid[nr][nc])
                total = 1 + sum(area_map[nid] for nid in neighbors)
                max_area = max(max_area, total)
    return max_area
